package com.dawnrise.identity.notification.securityevent;
import com.dawnrise.identity.notification.dto.*;import com.dawnrise.identity.notification.service.NotificationService;import com.dawnrise.identity.roleapproval.entity.RoleAssignmentApproval;import com.dawnrise.identity.roleapproval.policy.RoleApprovalPolicy;import com.dawnrise.identity.roleapproval.repository.*;import com.dawnrise.identity.roleremoval.policy.RoleRemovalApprovalPolicy;import com.dawnrise.identity.roleremoval.repository.*;import com.dawnrise.identity.user.enums.UserRole;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import org.springframework.jdbc.core.namedparam.*;import org.springframework.test.util.ReflectionTestUtils;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class RoleWorkflowNotificationAspectTest {@Test void targetsOnlyRemainingRequiredApproversAndDeduplicatesMultiRoleUsers(){NotificationService notifications=mock(NotificationService.class);NamedParameterJdbcTemplate jdbc=mock(NamedParameterJdbcTemplate.class);RoleApprovalPolicy policy=mock(RoleApprovalPolicy.class);RoleRemovalApprovalPolicy removalPolicy=mock(RoleRemovalApprovalPolicy.class);RoleAssignmentApprovalRepository approvals=mock(RoleAssignmentApprovalRepository.class);RoleAssignmentApproval prior=mock(RoleAssignmentApproval.class);when(prior.getApproverUserId()).thenReturn(20L);when(prior.getApproverRole()).thenReturn(UserRole.PRINCIPAL);when(prior.getDecision()).thenReturn(com.dawnrise.identity.roleapproval.enums.ApprovalDecision.APPROVED);when(approvals.findAllByRequestId(5L)).thenReturn(List.of(prior));when(policy.getRequiredApproverRoles(UserRole.ADMIN)).thenReturn(Set.of(UserRole.PRINCIPAL,UserRole.GOVERNING_AUTHORITY));when(jdbc.queryForList(anyString(),any(MapSqlParameterSource.class),eq(Long.class))).thenReturn(List.of(20L,21L,21L,10L,11L));RoleWorkflowNotificationAspect aspect=new RoleWorkflowNotificationAspect(notifications,jdbc,policy,removalPolicy,mock(RoleAssignmentRequestRepository.class),mock(RoleRemovalRequestRepository.class),approvals,mock(RoleRemovalApprovalRepository.class));ReflectionTestUtils.invokeMethod(aspect,"approvalRequired",1L,5L,10L,11L,UserRole.ADMIN,false);ArgumentCaptor<IngestNotificationRequest> request=ArgumentCaptor.forClass(IngestNotificationRequest.class);verify(notifications).ingest(eq("identity-service"),request.capture());assertEquals(Set.of(21L),request.getValue().recipientUserIds());assertTrue(request.getValue().sourceEventId().contains("GOVERNING_AUTHORITY"));}}
